import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import styled from 'styled-components';

// Styled Components
const Container = styled.div`
  padding: 20px;
  font-family: 'Arial', sans-serif;
`;

const Header = styled.h1`
  font-size: 2.5rem;
  color: #333;
  margin-bottom: 20px;
  text-align: center;
`;

const Button = styled.button`
  background-color: #4CAF50;
  color: white;
  border: none;
  padding: 10px 20px;
  font-size: 1rem;
  cursor: pointer;
  border-radius: 5px;
  transition: background-color 0.3s;

  &:hover {
    background-color: #45a049;
  }

  &:focus {
    outline: none;
  }
`;

const FormWrapper = styled.div`
  padding: 20px;
  max-width: 500px;
  margin: 0 auto;
  background-color: #f8f8f8;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const Title = styled.h2`
  font-size: 24px;
  color: #333;
  text-align: center;
  margin-bottom: 20px;
`;

const InputWrapper = styled.div`
  margin-bottom: 15px;
`;

const Label = styled.label`
  display: block;
  font-size: 14px;
  color: #555;
  margin-bottom: 5px;
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  font-size: 14px;
  border: 1px solid #ccc;
  border-radius: 4px;
  margin-bottom: 5px;
  background-color: #fff;

  &:focus {
    outline: none;
    border-color: #4caf50;
  }
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  font-size: 14px;
  border: 1px solid #ccc;
  border-radius: 4px;
  background-color: #fff;

  &:focus {
    outline: none;
    border-color: #4caf50;
  }
`;

const EmployeeColumns = styled.div`
  display: flex;
  justify-content: space-between;
  margin-top: 30px;
`;

const EmployeeColumn = styled.div`
  width: 23%;
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 20px;
  background-color: #f9f9f9;
`;

const EmployeeCard = styled.div`
  background-color: #fff;
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 15px;
  margin-bottom: 15px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
`;

const EmployeeTitle = styled.h4`
  font-size: 1.2rem;
  color: #333;
`;

const EmployeeDetails = styled.p`
  font-size: 1rem;
  color: #555;
  margin: 5px 0;
`;

const ErrorMessage = styled.div`
  background-color: #f8d7da;
  color: #721c24;
  padding: 15px;
  border-radius: 5px;
  margin-bottom: 20px;
  font-size: 1rem;
  text-align: center;
`;

const EmployeePage = () => {
  const { registrationNumber } = useParams();
  const [employees, setEmployees] = useState([]);
  const [error, setError] = useState(null);
  const [newEmployee, setNewEmployee] = useState({
    lorryId: registrationNumber,
    name: '',
    role: '',
    fixedSalary: '',
    salaryPerDay: ''
  });
  const [showAddEmployeeForm, setShowAddEmployeeForm] = useState(false);

  useEffect(() => {
    if (!registrationNumber) {
      console.error('Registration Number is undefined.');
      setError('Registration Number is missing. Please check the URL.');
      return;
    }

    axios
      .get(`http://localhost:5001/api/employees?lorryId=${registrationNumber}`)
      .then((response) => {
        setEmployees(response.data);
        setError(null);
      })
      .catch((error) => {
        console.error('Error fetching employee data:', error);
        setError('Failed to fetch employee data. Please try again later.');
      });
  }, [registrationNumber]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewEmployee((prevState) => ({
      ...prevState,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    axios
      .post('http://localhost:5001/api/employees', newEmployee)
      .then((response) => {
        setEmployees((prev) => [...prev, response.data]);
        setShowAddEmployeeForm(false);
        setNewEmployee({
          lorryId: registrationNumber,
          name: '',
          role: '',
          fixedSalary: '',
          salaryPerDay: ''
        });
        setError(null);
      })
      .catch((error) => {
        console.error('Error adding employee:', error);
        setError('Failed to add employee. Please try again later.');
      });
  };

  const filterEmployeesByRole = (role) => {
    return employees.filter((employee) => employee.role === role);
  };

  if (error) {
    return <ErrorMessage>{error}</ErrorMessage>;
  }

  return (
    <Container>
      <Header>Employees for Lorry {registrationNumber}</Header>

      <Button onClick={() => setShowAddEmployeeForm(!showAddEmployeeForm)}>
        {showAddEmployeeForm ? 'Cancel' : 'Add Employee'}
      </Button>

      {showAddEmployeeForm && (
        <FormWrapper>
          <Title>Add New Employee</Title>
          <form onSubmit={handleSubmit}>
            <InputWrapper>
              <Label htmlFor="name">Name</Label>
              <Input
                type="text"
                id="name"
                name="name"
                value={newEmployee.name}
                onChange={handleInputChange}
                required
                placeholder="Enter employee name"
              />
            </InputWrapper>

            <InputWrapper>
              <Label htmlFor="role">Role</Label>
              <Select
                id="role"
                name="role"
                value={newEmployee.role || ''}
                onChange={handleInputChange}
                required
              >
                <option value="" disabled>
                  Select role
                </option>
                <option value="driver">Driver</option>
                <option value="driller">Driller</option>
                <option value="manager">Lorry Manager</option>
                <option value="worker">Worker</option>
              </Select>
            </InputWrapper>

            <InputWrapper>
              <Label htmlFor="fixedSalary">Fixed Salary</Label>
              <Input
                type="number"
                id="fixedSalary"
                name="fixedSalary"
                value={newEmployee.fixedSalary}
                onChange={handleInputChange}
                required
                placeholder="Enter fixed salary"
              />
